function validate([street, k]) {
  if (!Array.isArray(street) || street.length < 1 || street.length > 100000) return 'street needs 1 to 100000 houses.';
  if (street.some(door => door !== 0 && door !== 1)) return 'Each door is 0 (closed) or 1 (open).';
  if (!street.includes(1)) return 'At least one door must be open.';
  if (!Number.isInteger(k) || k > 100000) return 'k is a whole number up to 100000.';
  if (k < street.length) return 'k must be at least the number of houses.';
  return null;
}

