function adapt(input, solve, kit) {
  const [doors, k] = input;
  const open = doors.map(door => door === 1);
  const n = open.length;
  let position = 0;
  // The door list stays inside this closure; the solution can only use the three methods.
  const street = Object.freeze({
    closeDoor() {
      open[position] = false;
    },
    isDoorOpen() {
      return open[position];
    },
    moveRight() {
      position = (position + 1) % n;
    },
  });
  return solve(street, k);
}

