function houseCount(street, k) {
  // Stand at an open door, then walk 2k steps, writing down each door before closing it.
  while (!street.isDoorOpen()) street.moveRight();
  const seen = [1];
  for (let step = 1; step <= 2 * k; step++) {
    street.moveRight();
    seen.push(street.isDoorOpen() ? 1 : 0);
    street.closeDoor();
  }
  // Try every possible length: replay the same walk on a street of that length and keep the one that fits.
  for (let length = 1; length <= k; length++) {
    const doors = seen.slice(0, length);
    let fits = true;
    for (let step = 1; step <= 2 * k && fits; step++) {
      const at = step % length;
      if (doors[at] !== seen[step]) fits = false;
      doors[at] = 0;
    }
    if (fits) return length;
  }
  return -1;
}

