function generate(rand, size) {
  const k = size === 'large' ? 50000 + Math.floor(rand() * 50001) : 1 + Math.floor(rand() * 10);
  const cap = size === 'large' ? 2000 : k;
  // Sometimes the street is as long as allowed, sometimes much shorter.
  const n = rand() < 0.3 ? cap : 1 + Math.floor(rand() * cap);
  const bias = rand();
  const street = Array.from({ length: n }, () => (rand() < bias ? 1 : 0));
  // The problem guarantees at least one open door.
  if (!street.includes(1)) street[Math.floor(rand() * n)] = 1;
  return [street, k];
}
